import java.text.*;
import java.util.*;
import org.joda.time.*;
import org.joda.time.format.*;
public class TsTest {
  public static void main(String[] args) throws Exception {
    SimpleDateFormat sdf = new SimpleDateFormat("yyyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
    String[] samples = {
      "2024-01-15T13:47:00.123Z",
      "2024-01-15T01:47:00.123Z",
      "02024-01-15T13:47:00.123Z"
    };
    for (String s : samples) {
      try {
        Date d = sdf.parse(s);
        System.out.println("PARSE yyyyy: " + s + " -> " + d + " millis=" + d.getTime());
      } catch (Exception e) {
        System.out.println("PARSE FAIL yyyyy: " + s + " " + e.getMessage());
      }
    }
    SimpleDateFormat sdf2 = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    sdf2.setTimeZone(TimeZone.getTimeZone("UTC"));
    for (String s : samples) {
      try {
        Date d = sdf2.parse(s);
        System.out.println("PARSE yyyy: " + s + " -> " + d);
      } catch (Exception e) {
        System.out.println("PARSE FAIL yyyy: " + s + " " + e.getMessage());
      }
    }
    // joda hh vs HH
    long afternoon = new DateTime(2024,1,15,13,47,0,123, DateTimeZone.UTC).getMillis();
    DateTimeFormatter fhh = DateTimeFormat.forPattern("yyyy-MM-dd'T'hh:mm:ss.SSS'Z'");
    DateTimeFormatter fHH = DateTimeFormat.forPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    DateTime dt = new DateTime(afternoon, DateTimeZone.UTC);
    System.out.println("hh: " + dt.toString(fhh));
    System.out.println("HH: " + dt.toString(fHH));
    long morning = new DateTime(2024,1,15,1,47,0,123, DateTimeZone.UTC).getMillis();
    DateTime dtm = new DateTime(morning, DateTimeZone.UTC);
    System.out.println("morning hh: " + dtm.toString(fhh));
    System.out.println("morning HH: " + dtm.toString(fHH));
    long midnight = new DateTime(2024,1,15,0,30,0,0, DateTimeZone.UTC).getMillis();
    DateTime dtn = new DateTime(midnight, DateTimeZone.UTC);
    System.out.println("midnight hh: " + dtn.toString(fhh));
    System.out.println("midnight HH: " + dtn.toString(fHH));
  }
}
EOF
